CREATE OR REPLACE FUNCTION fn_calcular_valor_reserva(p_checkin DATE,p_checkout DATE,p_valor_diaria NUMERIC) RETURNS NUMERIC(12,2) LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF p_checkin IS NULL OR p_checkout IS NULL THEN RAISE EXCEPTION 'As datas são obrigatórias.'; END IF; IF p_checkout<=p_checkin THEN RAISE EXCEPTION 'O check-out deve ser posterior ao check-in.'; END IF; IF p_valor_diaria IS NULL OR p_valor_diaria<=0 THEN RAISE EXCEPTION 'A diária deve ser maior que zero.'; END IF; RETURN (p_checkout-p_checkin)*p_valor_diaria; END; $$;
